username = input("Name: ")
while username != "Suesse":
    if username == "Cookie":
        print("Cookie ist Queen von allen und die beste")
    else:
        if username == "VoldiOhneNase":
            print("Wo ist meine Nase Frechdachs")
        else:
            if username == "Nick":
                print("Nein das ist falsch. Ich heiße Voldi")
            else:
                if username == "Ich liebe dich":
                    print("Voldi liebt seine Suesse mehr und mehr und am meisten.")
                else:
                    print("Falsche Person. Nicht gut")

    username = input("Name: ")

print("Du und dein Projekt sind toll")